import{_ as r,o as a,c as e,a2 as t}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"伺服Discord","description":"伺服的Discord 歡迎你的加入:D","frontmatter":{"title":"伺服Discord","description":"伺服的Discord 歡迎你的加入:D"},"headers":[],"relativePath":"discord/index.md","filePath":"discord.md"}'),o={name:"discord/index.md"};function d(l,i,s,c,h,n){return a(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="加入discord" tabindex="-1">加入Discord <a class="header-anchor" href="#加入discord" aria-label="Permalink to &quot;加入Discord&quot;">​</a></h1><p>一個很好用的通訊和聊天軟體，電腦與手機皆有支援</p><ul><li>註冊帳號 <a href="https://discord.com/" target="_blank" rel="noreferrer">https://discord.com/</a>(官方連結)</li></ul><h2 id="伺服discord的邀請連結" tabindex="-1">伺服Discord的邀請連結 <a class="header-anchor" href="#伺服discord的邀請連結" aria-label="Permalink to &quot;伺服Discord的邀請連結&quot;">​</a></h2><p><font size="4"><a href="https://discord.gg/nagiasu" target="_blank" rel="noreferrer">https://discord.gg/nagiasu</a></font></p><ul><li>點擊連結即可加入伺服的Discord</li></ul><h2 id="獲取玩家身分組" tabindex="-1">獲取玩家身分組 <a class="header-anchor" href="#獲取玩家身分組" aria-label="Permalink to &quot;獲取玩家身分組&quot;">​</a></h2><h3 id="如果你已經登入伺服了" tabindex="-1">如果你已經登入伺服了 <a class="header-anchor" href="#如果你已經登入伺服了" aria-label="Permalink to &quot;如果你已經登入伺服了&quot;">​</a></h3><ul><li>請參考下方的<b>連結綁定說明</b>進行身分綁定 <ul><li>綁定完成即會獲得<b>玩家</b>身分組</li></ul></li></ul><h3 id="如果你還沒登入過伺服" tabindex="-1">如果你還沒登入過伺服 <a class="header-anchor" href="#如果你還沒登入過伺服" aria-label="Permalink to &quot;如果你還沒登入過伺服&quot;">​</a></h3><ol><li>請先登入伺服</li><li>參考下方的<b>連結綁定說明</b>進行身分綁定</li></ol><h2 id="連結綁定說明" tabindex="-1">連結綁定說明 <a class="header-anchor" href="#連結綁定說明" aria-label="Permalink to &quot;連結綁定說明&quot;">​</a></h2><p>將你的Discord帳號與遊戲帳號進行連結<br> 可以使用多項同步功能(如同步聊天等)</p><h3 id="綁定方式-從未綁定過" tabindex="-1">綁定方式(從未綁定過) <a class="header-anchor" href="#綁定方式-從未綁定過" aria-label="Permalink to &quot;綁定方式(從未綁定過)&quot;">​</a></h3><ol><li>請先登入遊戲，以及加入<b>伺服Discord</b></li><li>在遊戲內輸入指令 <code>/link</code>後，你會得到一串六位數字<br><img src="https://i.imgur.com/7wyO0wM.png" style="height:12;width:12%;"><br><img src="https://i.imgur.com/ohViNuQ.png" style="height:60;width:60%;"></li><li>進入伺服Discord，找到下面『🎯身份綁定』<br><img src="https://i.imgur.com/A4FnSLt.png" style="height:30;width:30%;"></li><li>在該頻道內直接輸入六位數字<br><img src="https://i.imgur.com/Q2gMd0c.png" style="height:20;width:20%;"></li><li>當出現連結成功後，即完成綁定<br><img src="https://i.imgur.com/Med4SXI.png" style="height:35;width:35%;"></li><li>你可以確認是否擁有<b>玩家</b>身分組<br><img src="https://i.imgur.com/1vYGg1f.png" style="height:30;width:30%;"></li></ol><h3 id="綁定方式-曾經綁定過" tabindex="-1">綁定方式(曾經綁定過) <a class="header-anchor" href="#綁定方式-曾經綁定過" aria-label="Permalink to &quot;綁定方式(曾經綁定過)&quot;">​</a></h3><p>如果你已經綁定過，但沒有<b>玩家</b>身分組<br> (可能是因為你退出過群組，或是系統錯誤等原因導致)<br> 可以在『🎯身份綁定』(不是遊戲內) 輸入<code>/link</code>，系統會幫你將身分組加回來<br><img src="https://i.imgur.com/7dHe1BX.png" style="height:50;width:50%;"></p><div class="warning custom-block"><p class="custom-block-title">注意事項</p><p>當透過上述兩種方式皆無法成功綁定時，請使用<a href="/contact/">客服系統</a>由伺服人員協助處理</p></div><h3 id="解除綁定" tabindex="-1">解除綁定 <a class="header-anchor" href="#解除綁定" aria-label="Permalink to &quot;解除綁定&quot;">​</a></h3><p>如果你換過遊戲帳號或Discord帳號，或是個人因素等原因需要解除綁定</p><ul><li>請使用<a href="/discord/customer_service/">客服系統</a>請伺服人員協助處理</li></ul><h2 id="discord頻道說明" tabindex="-1">Discord頻道說明 <a class="header-anchor" href="#discord頻道說明" aria-label="Permalink to &quot;Discord頻道說明&quot;">​</a></h2><p><font size="4"><a href="/discord/text_channel/">點我查看 Discord文字頻道說明</a></font><font size="4"><a href="/discord/voice_channel/">點我查看 Discord語音頻道說明</a></font></p>',23)])])}const p=r(o,[["render",d]]);export{b as __pageData,p as default};
